<#
.SYNOPSIS
  Generates synthetic anime-shaped test media for Roxy TV.

  Each file carries a burned-in timecode (so A/V and subtitle sync is visible), a tone,
  the typeset.ass track, and the two fonts as MKV attachments. Files are small (synthetic
  video compresses well) but exercise the real decode paths: Hi10P H.264, HEVC Main10,
  4K HEVC HDR10, AV1, dual audio, external sidecar subtitles, plus (set 2) H.264 8-bit,
  HEVC 8-bit 60 fps with 5.1 audio, a Blu-ray-remux shape with TrueHD + PGS, HLG, and MP4.

.PARAMETER FFmpeg  Path to ffmpeg.exe (defaults to the jellyfin-ffmpeg portable build).
.PARAMETER Out     Output directory (default testdata/out, git-ignored).
.PARAMETER Seconds Duration of the 1080p files (default 60). The 4K file is capped at 20 s.
#>
param(
    [string]$FFmpeg = "$env:USERPROFILE\tools\jellyfin-ffmpeg\ffmpeg.exe",
    [string]$Out = "$PSScriptRoot\out",
    [int]$Seconds = 60,
    [switch]$SkipSlow,
    # Generate only these file names (e.g. -Only test-bluray-pgs.mkv,test-hlg-ass.mkv).
    [string[]]$Only
)

# ffmpeg writes progress to stderr; under "Stop" Windows PowerShell would treat that as a
# terminating error, so stay on "Continue" and check $LASTEXITCODE after every call.
$ErrorActionPreference = "Continue"
$here = $PSScriptRoot
$fonts = Join-Path $here "fonts"
$subs = Join-Path $here "subs"
$ass = Join-Path $subs "typeset.ass"
$srt = Join-Path $subs "simple.srt"
$noto = Join-Path $fonts "NotoSansCJKjp-Regular.otf"
$oswald = Join-Path $fonts "Oswald.ttf"
$sup = Join-Path $subs "bluray.sup"   # generated by tools/make-pgs.py

foreach ($f in @($FFmpeg, $ass, $srt, $noto, $oswald)) {
    if (-not (Test-Path $f)) { throw "Missing: $f" }
}
New-Item -ItemType Directory -Force $Out | Out-Null

function Wanted([string]$name) { return (-not $Only) -or ($Only -contains $name) }

# Multichannel test tone: a different frequency per channel so channel mapping is audible
# (FL 440, FR 660, FC 880, LFE 60, BL 330, BR 495 Hz).
$tone51 = "aevalsrc=exprs=0.3*sin(440*2*PI*t)|0.3*sin(660*2*PI*t)|0.3*sin(880*2*PI*t)|0.3*sin(60*2*PI*t)|0.3*sin(330*2*PI*t)|0.3*sin(495*2*PI*t):channel_layout=5.1:sample_rate=48000"
$toneStereo = "aevalsrc=exprs=0.3*sin(440*2*PI*t)|0.3*sin(660*2*PI*t):channel_layout=stereo:sample_rate=48000"

# Burned-in timecode so the tester can see sync and seeking at a glance.
# drawtext needs a font file; use Oswald so this works on any machine.
$oswaldFf = ($oswald -replace '\\', '/') -replace ':', '\:'
$timecode = "drawtext=fontfile='$oswaldFf':text='%{pts\:hms}  frame %{n}':fontsize=48:fontcolor=white:box=1:boxcolor=black@0.6:x=40:y=40"

# Common inputs: synthetic video, sine tone, ASS track, fonts as attachments.
function Common-Args([string]$size, [string]$rate, [int]$t) {
    return @(
        "-y", "-hide_banner", "-loglevel", "warning", "-stats",
        "-f", "lavfi", "-i", "testsrc2=size=${size}:rate=${rate}",
        "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000",
        "-i", $ass,
        "-attach", $noto, "-metadata:s:t:0", "mimetype=application/vnd.ms-opentype", "-metadata:s:t:0", "filename=NotoSansCJKjp-Regular.otf",
        "-attach", $oswald, "-metadata:s:t:1", "mimetype=application/x-truetype-font", "-metadata:s:t:1", "filename=Oswald.ttf",
        "-t", "$t",
        "-map", "0:v", "-map", "1:a", "-map", "2:s",
        "-vf", $timecode,
        "-metadata:s:a:0", "language=jpn", "-metadata:s:s:0", "language=eng", "-metadata:s:s:0", "title=Roxy typeset test",
        "-c:s", "copy"
    )
}

function Run([string]$name, [string[]]$ffArgs) {
    if (-not (Wanted $name)) { return }
    $outFile = Join-Path $Out $name
    Write-Host "==> $name" -ForegroundColor Cyan
    $sw = [Diagnostics.Stopwatch]::StartNew()
    & $FFmpeg @ffArgs $outFile
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for $name (exit $LASTEXITCODE)" }
    $sw.Stop()
    "{0,-34} {1,8:N1} MB  {2,6:N0} s" -f $name, ((Get-Item $outFile).Length / 1MB), $sw.Elapsed.TotalSeconds
}

# 1. Hi10P: H.264 High 10 at 1080p. No TV decodes this in hardware; proves software decode + libass.
Run "test-hi10p-ass.mkv" ((Common-Args "1920x1080" "24000/1001" $Seconds) + @(
    "-c:v", "libx264", "-profile:v", "high10", "-pix_fmt", "yuv420p10le", "-preset", "veryfast", "-crf", "18", "-g", "48",
    "-c:a", "aac", "-b:a", "160k"
))

# 2. HEVC Main10 1080p with FLAC audio: the common modern anime release shape.
Run "test-hevc10-ass.mkv" ((Common-Args "1920x1080" "24000/1001" $Seconds) + @(
    "-c:v", "libx265", "-profile:v", "main10", "-pix_fmt", "yuv420p10le", "-preset", "ultrafast", "-crf", "20", "-x265-params", "keyint=48:log-level=error",
    "-c:a", "flac"
))

# 3. Dual audio (FLAC jpn + E-AC-3 eng), ASS + SRT embedded, plus a Bazarr-style sidecar.
$dual = Join-Path $Out "test-dualaudio-ass.mkv"
if (Wanted "test-dualaudio-ass.mkv") {
Write-Host "==> test-dualaudio-ass.mkv" -ForegroundColor Cyan
& $FFmpeg -y -hide_banner -loglevel warning -stats `
    -f lavfi -i "testsrc2=size=1920x1080:rate=24000/1001" `
    -f lavfi -i "sine=frequency=440:sample_rate=48000" `
    -f lavfi -i "sine=frequency=880:sample_rate=48000" `
    -i $ass -i $srt `
    -attach $noto -metadata:s:t:0 "mimetype=application/vnd.ms-opentype" -metadata:s:t:0 "filename=NotoSansCJKjp-Regular.otf" `
    -attach $oswald -metadata:s:t:1 "mimetype=application/x-truetype-font" -metadata:s:t:1 "filename=Oswald.ttf" `
    -t $Seconds `
    -map 0:v -map 1:a -map 2:a -map 3:s -map 4:s `
    -vf $timecode `
    -c:v libx265 -profile:v main10 -pix_fmt yuv420p10le -preset ultrafast -crf 20 -x265-params "keyint=48:log-level=error" `
    -c:a:0 flac -metadata:s:a:0 language=jpn -metadata:s:a:0 title="Japanese FLAC" `
    -c:a:1 eac3 -b:a:1 256k -metadata:s:a:1 language=eng -metadata:s:a:1 title="English E-AC-3" `
    -c:s copy -metadata:s:s:0 language=eng -metadata:s:s:0 title="Full subs (ASS)" -metadata:s:s:1 language=eng -metadata:s:s:1 title="Signs (SRT)" `
    $dual
if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for dual audio" }
Copy-Item $ass (Join-Path $Out "test-dualaudio-ass.en.ass") -Force
Copy-Item $srt (Join-Path $Out "test-dualaudio-ass.en.forced.srt") -Force
"{0,-34} {1,8:N1} MB" -f "test-dualaudio-ass.mkv", ((Get-Item $dual).Length / 1MB)
}

# 6. H.264 8-bit High with stereo AAC: the most common format of all (older releases, web rips).
Run "test-h264-8bit-ass.mkv" ((Common-Args "1920x1080" "24000/1001" $Seconds) + @(
    "-c:v", "libx264", "-profile:v", "high", "-pix_fmt", "yuv420p", "-preset", "veryfast", "-crf", "18", "-g", "48",
    "-c:a", "aac", "-b:a", "160k"
))

# 7. HEVC 8-bit at 60 fps with 5.1 audio (FLAC jpn + E-AC-3 eng). Checks high frame rate hwdec
#    and multichannel decode / channel mapping / passthrough.
if (Wanted "test-hevc8-60fps-51-ass.mkv") {
    $f51 = Join-Path $Out "test-hevc8-60fps-51-ass.mkv"
    Write-Host "==> test-hevc8-60fps-51-ass.mkv" -ForegroundColor Cyan
    & $FFmpeg -y -hide_banner -loglevel warning -stats `
        -f lavfi -i "testsrc2=size=1920x1080:rate=60" `
        -f lavfi -i $tone51 `
        -f lavfi -i $tone51 `
        -i $ass `
        -attach $noto -metadata:s:t:0 "mimetype=application/vnd.ms-opentype" -metadata:s:t:0 "filename=NotoSansCJKjp-Regular.otf" `
        -attach $oswald -metadata:s:t:1 "mimetype=application/x-truetype-font" -metadata:s:t:1 "filename=Oswald.ttf" `
        -t $Seconds `
        -map 0:v -map 1:a -map 2:a -map 3:s `
        -vf $timecode `
        -c:v libx265 -profile:v main -pix_fmt yuv420p -preset ultrafast -crf 22 -x265-params "keyint=120:log-level=error" `
        -c:a:0 flac -metadata:s:a:0 language=jpn -metadata:s:a:0 title="Japanese FLAC 5.1" `
        -c:a:1 eac3 -b:a:1 640k -metadata:s:a:1 language=eng -metadata:s:a:1 title="English E-AC-3 5.1" `
        -c:s copy -metadata:s:s:0 language=eng -metadata:s:s:0 title="Roxy typeset test" `
        $f51
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for hevc8 60fps 5.1" }
    "{0,-34} {1,8:N1} MB" -f "test-hevc8-60fps-51-ass.mkv", ((Get-Item $f51).Length / 1MB)
}

# 8. Blu-ray remux shape: H.264 8-bit High, TrueHD 5.1 (jpn) + AC-3 5.1 (eng), PGS bitmap subs,
#    no ASS and no fonts. TrueHD/DCA encoders are experimental in FFmpeg; good enough for decode tests.
if (Wanted "test-bluray-pgs.mkv") {
    if (-not (Test-Path $sup)) { throw "Missing $sup; run: python tools\make-pgs.py --ffmpeg <ffmpeg> --font fonts\Oswald.ttf --out subs\bluray.sup" }
    $bd = Join-Path $Out "test-bluray-pgs.mkv"
    Write-Host "==> test-bluray-pgs.mkv" -ForegroundColor Cyan
    & $FFmpeg -y -hide_banner -loglevel warning -stats `
        -f lavfi -i "testsrc2=size=1920x1080:rate=24000/1001" `
        -f lavfi -i $tone51 `
        -f lavfi -i $tone51 `
        -i $sup `
        -t $Seconds `
        -map 0:v -map 1:a -map 2:a -map 3:s `
        -vf $timecode `
        -c:v libx264 -profile:v high -pix_fmt yuv420p -preset veryfast -crf 18 -g 48 `
        -strict experimental `
        -c:a:0 truehd -metadata:s:a:0 language=jpn -metadata:s:a:0 title="Japanese TrueHD 5.1" `
        -c:a:1 ac3 -b:a:1 640k -metadata:s:a:1 language=eng -metadata:s:a:1 title="English AC-3 5.1" `
        -c:s copy -metadata:s:s:0 language=eng -metadata:s:s:0 title="English PGS" `
        $bd
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for bluray pgs" }
    "{0,-34} {1,8:N1} MB" -f "test-bluray-pgs.mkv", ((Get-Item $bd).Length / 1MB)
}

# 9. HEVC Main10 1080p HLG (BT.2020, ARIB STD-B67): the other HDR flavour; no static metadata.
Run "test-hevc10-hlg-ass.mkv" ((Common-Args "1920x1080" "24000/1001" $Seconds) + @(
    "-c:v", "libx265", "-profile:v", "main10", "-pix_fmt", "yuv420p10le", "-preset", "ultrafast", "-crf", "20",
    "-x265-params", "keyint=48:log-level=error:colorprim=bt2020:transfer=arib-std-b67:colormatrix=bt2020nc:repeat-headers=1",
    "-c:a", "aac", "-b:a", "160k"
))

# 10. MP4 container with H.264 + AAC + mov_text subs (web rips). No attachments possible in MP4.
if (Wanted "test-h264-mp4-movtext.mp4") {
    $mp4 = Join-Path $Out "test-h264-mp4-movtext.mp4"
    Write-Host "==> test-h264-mp4-movtext.mp4" -ForegroundColor Cyan
    & $FFmpeg -y -hide_banner -loglevel warning -stats `
        -f lavfi -i "testsrc2=size=1920x1080:rate=24000/1001" `
        -f lavfi -i $toneStereo `
        -i $srt `
        -t $Seconds `
        -map 0:v -map 1:a -map 2:s `
        -vf $timecode `
        -c:v libx264 -profile:v high -pix_fmt yuv420p -preset veryfast -crf 18 -g 48 `
        -c:a aac -b:a 160k -metadata:s:a:0 language=jpn `
        -c:s mov_text -metadata:s:s:0 language=eng `
        -movflags +faststart `
        $mp4
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for mp4" }
    "{0,-34} {1,8:N1} MB" -f "test-h264-mp4-movtext.mp4", ((Get-Item $mp4).Length / 1MB)
}

# 11. Symbol / emoji fallback: H.264 8-bit with subs/symbols.ass and NO font attachments, so
#     every glyph has to come from the player's bundled fallback fonts.
if (Wanted "test-symbols-fallback.mkv") {
    $sym = Join-Path $Out "test-symbols-fallback.mkv"
    Write-Host "==> test-symbols-fallback.mkv" -ForegroundColor Cyan
    & $FFmpeg -y -hide_banner -loglevel warning -stats `
        -f lavfi -i "testsrc2=size=1920x1080:rate=24000/1001" `
        -f lavfi -i $toneStereo `
        -i (Join-Path $subs "symbols.ass") `
        -t 30 `
        -map 0:v -map 1:a -map 2:s `
        -vf $timecode `
        -c:v libx264 -profile:v high -pix_fmt yuv420p -preset veryfast -crf 18 -g 48 `
        -c:a aac -b:a 128k -metadata:s:a:0 language=jpn `
        -c:s copy -metadata:s:s:0 language=eng -metadata:s:s:0 title="Symbols fallback test" `
        $sym
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for symbols" }
    "{0,-34} {1,8:N1} MB" -f "test-symbols-fallback.mkv", ((Get-Item $sym).Length / 1MB)
}

# Not synthesizable here: Dolby Vision (needs an RPU; take a real profile 8.1 sample from the
# library when the server is back) and VobSub (dvdsub encoder needs bitmap input).

if (-not $SkipSlow) {
    # 4. 4K HEVC Main10 HDR10 (PQ, BT.2020, mastering metadata). Proves hwdec at 4K + HDR output + libass at a 4K canvas.
    $t4k = [Math]::Min($Seconds, 20)
    # NOTE: with jellyfin-ffmpeg 8.1 + libx265, ffmpeg-level -color_primaries/-color_trc are
    # NOT written to the stream; the colour signalling must go through x265-params.
    Run "test-hevc10-hdr10-4k-ass.mkv" ((Common-Args "3840x2160" "24000/1001" $t4k) + @(
        "-c:v", "libx265", "-profile:v", "main10", "-pix_fmt", "yuv420p10le", "-preset", "ultrafast", "-crf", "22",
        "-x265-params", "keyint=48:log-level=error:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc:hdr10=1:repeat-headers=1:master-display=G(13250,34500)B(7500,3000)R(34000,16000)WP(15635,16450)L(10000000,1):max-cll=1000,400",
        "-c:a", "eac3", "-b:a", "256k"
    ))

    # 5. AV1 (SVT-AV1) 1080p 10-bit with Opus. Newer groups; checks AV1 decode on the device.
    $tAv1 = [Math]::Min($Seconds, 30)
    Run "test-av1-10bit-ass.mkv" ((Common-Args "1920x1080" "24000/1001" $tAv1) + @(
        "-c:v", "libsvtav1", "-pix_fmt", "yuv420p10le", "-preset", "10", "-crf", "35", "-g", "48",
        "-c:a", "libopus", "-b:a", "128k"
    ))
}

Write-Host "`nDone. Files in $Out" -ForegroundColor Green
